amount = 500   # raqam badal kar dekhein

class Payment:
    def processPayment(self, amount):
        print("Processing", amount)

class CreditCard(Payment):
    def processPayment(self, amount):
        print("Charging card:", amount)

class NetBanking(Payment):
    def processPayment(self, amount):
        print("Redirecting to bank login for", amount)

for method in [CreditCard(), NetBanking(), Payment()]:
    method.processPayment(amount)
